using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Instructor> _instructors;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _instructors = new List<Instructor>
        {
            new() { Id = 1, Name = "Dr. Sarah Chen", Title = "Professor of Computer Science", Bio = "Dr. Chen specializes in distributed systems and cloud computing. She has published over 50 papers and holds three patents in fault-tolerant system design.", Email = "s.chen@university.edu" },
            new() { Id = 2, Name = "Dr. James Wright", Title = "Associate Professor of Mathematics", Bio = "Dr. Wright's research focuses on applied mathematics and statistical modeling. He previously worked at NASA's Jet Propulsion Laboratory.", Email = "j.wright@university.edu" },
            new() { Id = 3, Name = "Dr. Maria Rodriguez", Title = "Professor of Biology", Bio = "Dr. Rodriguez leads the university's genomics lab and has received multiple NSF grants for her work in evolutionary biology.", Email = "m.rodriguez@university.edu" },
            new() { Id = 4, Name = "Dr. David Kim", Title = "Assistant Professor of English", Bio = "Dr. Kim is a published novelist and literary critic specializing in contemporary American fiction and creative writing pedagogy.", Email = "d.kim@university.edu" },
            new() { Id = 5, Name = "Dr. Emily Foster", Title = "Professor of Physics", Bio = "Dr. Foster conducts research in quantum optics and has been recognized with the university's Distinguished Teaching Award three times.", Email = "e.foster@university.edu" },
            new() { Id = 6, Name = "Dr. Robert Patel", Title = "Associate Professor of History", Bio = "Dr. Patel is an expert in modern European history with a focus on 20th-century political movements and their cultural impacts.", Email = "r.patel@university.edu" },
        };

        _departments = new List<Department>
        {
            new() { Id = 1, Name = "Computer Science", Code = "CS", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Name = "Mathematics", Code = "MATH", Description = "Exploration of abstract structures, quantities, and patterns." },
            new() { Id = 3, Name = "Biology", Code = "BIO", Description = "Study of living organisms, their structure, function, and evolution." },
            new() { Id = 4, Name = "English", Code = "ENG", Description = "Study of literature, writing, and linguistic expression." },
            new() { Id = 5, Name = "Physics", Code = "PHYS", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 6, Name = "History", Code = "HIST", Description = "Study of past events, societies, and civilizations." },
        };

        _courses = new List<Course>
        {
            new() { Id = 1, Code = "CS 101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using Python. Covers variables, control structures, functions, and basic data structures. No prior experience required.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", DepartmentId = 1, InstructorId = 1, IsFeatured = true },
            new() { Id = 2, Code = "CS 301", Title = "Data Structures & Algorithms", Description = "Advanced study of data organization and algorithm design. Topics include trees, graphs, hash tables, sorting algorithms, and complexity analysis.", Credits = 4, Schedule = "Tue/Thu 10:00–11:50 AM", DepartmentId = 1, InstructorId = 1 },
            new() { Id = 3, Code = "CS 450", Title = "Cloud Computing", Description = "Principles of distributed cloud architectures, containerization, orchestration, and scalable system design. Includes hands-on labs with major cloud platforms.", Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", DepartmentId = 1, InstructorId = 1, IsFeatured = true },
            new() { Id = 4, Code = "MATH 201", Title = "Linear Algebra", Description = "Study of vector spaces, linear transformations, matrices, determinants, and eigenvalues. Applications to computer graphics and data science.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", DepartmentId = 2, InstructorId = 2 },
            new() { Id = 5, Code = "MATH 301", Title = "Probability & Statistics", Description = "Introduction to probability theory, random variables, distributions, hypothesis testing, and regression analysis.", Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", DepartmentId = 2, InstructorId = 2, IsFeatured = true },
            new() { Id = 6, Code = "BIO 101", Title = "General Biology", Description = "Survey of biological principles including cell biology, genetics, evolution, and ecology. Includes weekly laboratory sessions.", Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM + Lab Thu 2:00–4:50 PM", DepartmentId = 3, InstructorId = 3 },
            new() { Id = 7, Code = "BIO 320", Title = "Genetics & Genomics", Description = "Molecular genetics, gene expression, genome organization, and modern genomic technologies including CRISPR and sequencing methods.", Credits = 4, Schedule = "Tue/Thu 9:00–10:20 AM", DepartmentId = 3, InstructorId = 3, IsFeatured = true },
            new() { Id = 8, Code = "ENG 102", Title = "Academic Writing", Description = "Develop skills in analytical writing, research methods, argumentation, and revision. Focus on clear, effective communication in academic contexts.", Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", DepartmentId = 4, InstructorId = 4 },
            new() { Id = 9, Code = "ENG 350", Title = "Creative Writing Workshop", Description = "Workshop-based course in fiction and poetry writing. Students produce original works and participate in peer critique sessions.", Credits = 3, Schedule = "Wed 3:00–5:50 PM", DepartmentId = 4, InstructorId = 4 },
            new() { Id = 10, Code = "PHYS 201", Title = "Classical Mechanics", Description = "Newtonian mechanics, conservation laws, oscillations, and an introduction to Lagrangian mechanics. Calculus-based approach.", Credits = 4, Schedule = "Mon/Wed/Fri 9:00–9:50 AM + Lab Tue 1:00–3:50 PM", DepartmentId = 5, InstructorId = 5 },
            new() { Id = 11, Code = "PHYS 410", Title = "Quantum Mechanics", Description = "Introduction to quantum theory: wave functions, Schrödinger equation, angular momentum, spin, and applications to atomic physics.", Credits = 3, Schedule = "Tue/Thu 10:00–11:20 AM", DepartmentId = 5, InstructorId = 5, IsFeatured = true },
            new() { Id = 12, Code = "HIST 101", Title = "World History to 1500", Description = "Survey of major civilizations, cultural developments, and historical turning points from antiquity through the late medieval period.", Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:20 PM", DepartmentId = 6, InstructorId = 6 },
            new() { Id = 13, Code = "HIST 340", Title = "Modern European History", Description = "Political, social, and cultural history of Europe from the French Revolution to the present. Emphasis on ideological movements and their consequences.", Credits = 3, Schedule = "Mon/Wed 3:30–4:50 PM", DepartmentId = 6, InstructorId = 6 },
        };
    }

    public IReadOnlyList<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public IReadOnlyList<Course> GetCourses() => _courses;

    public IReadOnlyList<Course> SearchCourses(string? searchTerm, int? departmentId)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue && departmentId.Value > 0)
        {
            query = query.Where(c => c.DepartmentId == departmentId.Value);
        }

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim().ToLowerInvariant();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public IReadOnlyList<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public IReadOnlyList<Course> GetCoursesByDepartment(int departmentId) =>
        _courses.Where(c => c.DepartmentId == departmentId).ToList();

